    elif a <= 45:
        return '36-45'
    elif a <= 55:
        return '46-55'
    else:
        return '55+'


def income_to_slab(income):
    x = float(income)
    if (x > 0) and (x <= 5000):
        return 'Upto 5k'
    elif (x > 5000) and (x <= 10000):
        return '5k-10k'
    elif (x > 10000) and (x <= 15000):
        return '10k-15k'
    else:
        return '15k+'


def slab_bounds(slab):
    if slab == 'Upto 5k':
        return (0.0, 5000.0)
    if slab == '5k-10k':
        return (5000.0, 10000.0)
    if slab == '10k-15k':
        return (10000.0, 15000.0)
    if slab == '15k+':
        return (15000.0, None)
    return (None, None)


def within_slab_position(income, slab):
    lower, upper = slab_bounds(slab)
    x = float(income)
    if upper is None:
        return 0.0
    denom = (upper - lower)
    if denom <= 0:
        return 0.0
    val = (upper - x) / denom
    if val < 0:
        return 0.0
    if val > 1:
